package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

//Don't have to see. start------------------------------------------
var inLine []string
var index int
var max int
var writer *bufio.Writer

func hasNext() bool {
	return index < max
}

func next() string {
	if hasNext() {
		s := inLine[index]
		index++
		return s
	}
	panic("ArrayIndexOutOfBoundsException There is no more input")
}

func nextInt() int {
	return myconv1(next())
}

func nextStrArray() []string {
	return myconv2(next())
}

func nextIntArray() []int {
	return myconv4(next())
}

func nextCharArray() []string {
	return myconv6(next())
}

func myconv1(i string) int {
	v, err := strconv.Atoi(strings.TrimSpace(i))
	if err != nil {
		return 0
	}
	return v
}

func myconv2(i string) []string {
	return strings.Split(i, " ")
}

func myconv4(i string) []int {
	tmp := strings.Split(i, " ")
	ret := make([]int, len(tmp))
	for j := 0; j < len(tmp); j++ {
		ret[j] = myconv1(tmp[j])
	}
	return ret
}

func myconv6(i string) []string {
	return strings.Split(i, "")
}

func myconv7(i string) []int {
	tmp := strings.Split(i, "")
	ret := make([]int, len(tmp))
	for j := 0; j < len(tmp); j++ {
		ret[j] = myconv1(tmp[j])
	}
	return ret
}

func myconv8(i []string) string {
	return strings.Join(i, " ")
}

func myconv9(i []string) string {
	return strings.Join(i, "\n")
}

func myconv0(i []string) string {
	return strings.Join(i, "")
}

func myout(s string) {
	fmt.Fprintln(writer, s)
}

func myerr(s interface{}) {
	fmt.Fprintln(os.Stderr, "debug:", s)
}

//Don't have to see. end------------------------------------------

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	for scanner.Scan() {
		inLine = append(inLine, scanner.Text())
	}
	index = 0
	max = len(inLine)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	Main()
}

func Main() {
	nextInt()
	s := strings.Split(next(), "W")
	output := []string{}
	for i := 0; i < len(s); i++ {
		if s[i] != "" {
			output = append(output, strconv.Itoa(len(s[i])))
		}
	}
	myout(strconv.Itoa(len(output)))
	myout(myconv8(output))
}

